// Operatori Ternar (Kushti ? PjesaTrue : PjesaFalse)
int time = 20;
string result = (time < 18) ? "Dite e mire." : "Mbremje e mire.";
Console.WriteLine(result);

// Deklarata Switch me Default
int day = 4;
switch (day) {
  case 6: Console.WriteLine("E Shtune"); break;
  case 7: Console.WriteLine("E Djele"); break;
  default: Console.WriteLine("Dite jave"); break;
}
